output_text:
[
  {
    "id": "return_cart_to_top_left_bay",
    "text": "A customer who uses a cart is obliged to return it to the top-left cart bay before the trip is over.",
    "abstraction": {
      "state_properties": {
        "top_left_cart_bay": "at(0,1)",
        "cart_returned_to_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "cart_returned": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "top_left_cart_bay"
            ]
          },
          "post": "cart_returned_to_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "cart_returned"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Customers are prohibited from exiting the supermarket while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_possession": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "cart_in_possession"
        ]
      }
    }
  },
  {
    "id": "park_cart_only_at_return_bay",
    "text": "Customers may put down a cart only at the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "designated_cart_return_bay": "at(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "LEAVE_CART",
          {
            "not": "designated_cart_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "must_take_available_cart",
    "text": "A customer starting near the entrance is obliged to take the available cart before shopping.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_item_pickup_without_cart",
    "text": "Customers are prohibited from picking up shelf items unless they currently have a cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_possession": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "PICKUP_ITEM",
          {
            "not": "cart_in_possession"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying_merchandise",
    "text": "Customers are prohibited from carrying merchandise by hand rather than placing it in a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "use_equivalent_product_counters",
    "text": "Item pickup interactions are allowed only at recognized product counters, treating upper and lower displays of the same product as equivalent.",
    "abstraction": {
      "state_properties": {
        "bread_counter": {
          "or": [
            "at(3,2)",
            "at(3,4)"
          ]
        },
        "milk_counter": {
          "or": [
            "at(5,2)",
            "at(5,4)"
          ]
        },
        "eggs_counter": {
          "or": [
            "at(6,2)",
            "at(6,4)"
          ]
        },
        "apple_counter": "at(1,3)",
        "recognized_product_counter": {
          "or": [
            "bread_counter",
            "milk_counter",
            "eggs_counter",
            "apple_counter"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "PICKUP_ITEM",
          {
            "not": "recognized_product_counter"
          }
        ]
      }
    }
  },
  {
    "id": "only_cart_or_product_interactions",
    "text": "All interactions must be either taking the entrance cart, picking up an item at a recognized product counter, or returning the cart at the return bay.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "cart_return_bay": "at(0,1)",
        "bread_counter": {
          "or": [
            "at(3,2)",
            "at(3,4)"
          ]
        },
        "milk_counter": {
          "or": [
            "at(5,2)",
            "at(5,4)"
          ]
        },
        "eggs_counter": {
          "or": [
            "at(6,2)",
            "at(6,4)"
          ]
        },
        "apple_counter": "at(1,3)",
        "recognized_product_counter": {
          "or": [
            "bread_counter",
            "milk_counter",
            "eggs_counter",
            "apple_counter"
          ]
        },
        "permitted_interaction_place": {
          "or": [
            "entrance_cart_station",
            "cart_return_bay",
            "recognized_product_counter"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "permitted_interaction_place"
          }
        ]
      }
    }
  }
]
